from records import BuildUpload


def record_duration(upload, seconds, sink):
    kind = "manual"
    if isinstance(upload, BuildUpload):
        kind = upload.build.kind
    sink.timing("upload_duration", seconds * 1000, {"type": kind})

from dataclasses import dataclass


@dataclass(frozen=True)
class Build:
    kind: str


@dataclass(frozen=True)
class BuildUpload:
    leaf: str
    build: Build | None


@dataclass(frozen=True)
class UserUpload:
    leaf: str
